export function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>'"]/gu, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[char]))
}

export function safeUrl(value) {
  if (typeof value !== 'string' || !value.trim()) return null
  try { const url = new URL(value.trim()); return ['http:', 'https:'].includes(url.protocol) ? url.href : null } catch { return null }
}

export function formatMetric(value) {
  if (value === null || value === undefined || value === '') return '—'
  const number = Number(value)
  if (!Number.isFinite(number)) return String(value)
  if (number >= 100000) return `${Math.floor(number / 10000)}万+`
  if (number >= 10000) return `${Number((number / 10000).toFixed(2))}万`
  return new Intl.NumberFormat('zh-CN', { maximumFractionDigits: 2 }).format(number)
}

export function formatDateTime(value) {
  if (value === null || value === undefined || value === '') return '—'
  const parsed = new Date(value)
  if (Number.isNaN(parsed.getTime())) return String(value)
  const parts = new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }).format(parsed)
  return parts.replaceAll('/', '-')
}

export function pageLabel({ page, pageSize, total, loadedCount, hasNext = false }) {
  if (total === null || total === undefined) return `已加载 ${(Math.max(0, page - 1) * pageSize) + loadedCount} 条${hasNext ? '' : '，已到当前数据末尾'}`
  if (!total) return '暂无记录'
  const start = (page - 1) * pageSize + 1
  const end = Math.min(start + loadedCount - 1, total)
  return `第 ${start}–${end} 条，共 ${total} 条`
}

export function debounce(fn, wait = 400) {
  let timer = null
  const wrapped = (...args) => { clearTimeout(timer); timer = setTimeout(() => { timer = null; fn(...args) }, wait) }
  wrapped.cancel = () => { clearTimeout(timer); timer = null }
  return wrapped
}

