function toast(message, { actionLabel = '', onAction = null } = {}) {
  const node = $('#toast')
  node.replaceChildren()
  const textNode = document.createElement('span')
  textNode.textContent = message
  node.append(textNode)
  if (actionLabel && typeof onAction === 'function') {
    const action = document.createElement('button')
    action.type = 'button'
    action.className = 'toast-action'
    action.textContent = actionLabel
    action.addEventListener('click', () => { node.classList.remove('show'); onAction() }, { once: true })
    node.append(action)
  }
  node.classList.add('show')
  clearTimeout(toastTimer)
  toastTimer = setTimeout(() => node.classList.remove('show'), actionLabel ? 5000 : 2800)
}
function errorText(error) { return error?.status === 409 ? '数据已被其他操作修改，请刷新后重试' : error?.status === 501 ? '执行器未接入/凭据未就绪' : error?.status === 503 ? '服务未就绪，请检查本机 Supabase 连接' : error?.message || '请求失败' }
