function accountFixedFieldKeys() { return new Set(ACCOUNT_FIXED_COLUMNS.filter(column => column.source && column.field !== 'type_region').map(column => `${column.source}.${column.field}`)) }
function accountColumnSettings() { return [...ACCOUNT_COLUMN_FIELDS.account.map(field => ({ key: `account.${field}`, source: 'account', field })), ...ACCOUNT_COLUMN_FIELDS.profile.map(field => ({ key: `profile.${field}`, source: 'profile', field }))] }
function readAccountColumnPreference() { try { const raw = localStorage.getItem(ACCOUNT_STORAGE_KEY); const parsed = JSON.parse(raw || '[]'); return Array.isArray(parsed) ? parsed.filter(key => accountColumnSettings().some(column => column.key === key)) : [] } catch { return [] } }
function saveAccountColumnPreference(key, checked) { const next = new Set(readAccountColumnPreference()); if (checked) next.add(key); else next.delete(key); try { localStorage.setItem(ACCOUNT_STORAGE_KEY, JSON.stringify([...next])) } catch {} }
function accountColumnLabel(column) { if (column.source === 'profile' && column.field === 'account_id') return '详情 account_id'; if (column.source === 'profile' && ['read_median', 'read_max'].includes(column.field)) return `详情${ACCOUNT_COLUMN_LABELS[column.field].replace('账号', '')}`; return ACCOUNT_COLUMN_LABELS[column.field] || column.field }
function accountColumnSettingsMarkup() { const fixed = accountFixedFieldKeys(); const selected = new Set(readAccountColumnPreference()); return `<div class="column-panel-head"><strong>列设置</strong><span>固定列始终显示，其他列保存在本机浏览器。</span></div><div class="column-settings-grid">${accountColumnSettings().map(column => `<label class="column-setting"><input type="checkbox" data-account-column="${esc(column.key)}" ${fixed.has(column.key) ? 'checked disabled' : selected.has(column.key) ? 'checked' : ''}><span>${esc(accountColumnLabel(column))}</span></label>`).join('')}</div>` }
