function submitAccountFilter(form) { state.query = Object.fromEntries(new FormData(form)); state.page = 1; state.selectedAccountIds.clear(); state.accountFocusedIndex = -1; api.invalidate('accounts:list'); updateAccountStatusTabs(); loadAccounts() }
function setAccountStatus(status) { const form = $('#account-filter'); if (form?.elements.status) form.elements.status.value = status; state.query = { ...state.query, status }; if (!status) delete state.query.status; state.page = 1; state.selectedAccountIds.clear(); state.accountFocusedIndex = -1; api.invalidate('accounts:list'); updateAccountStatusTabs(); loadAccounts() }
function updateAccountStatusTabs() { const active = String(state.query.status || ''); document.querySelectorAll('[data-account-status]').forEach(node => node.classList.toggle('active', node.dataset.accountStatus === active)); }
function accountFieldValue(row, column) { if (column.source === 'account') return row[column.field]; if (column.field === 'type_region') return `${row.profile_wx_type ?? ''} / ${row.profile_region ?? ''}`; return row[`profile_${column.field}`] }
function accountTags(value) { let values = value; if (typeof values === 'string') { try { values = JSON.parse(values) } catch { values = values.split(/[，,\n]/u) } } if (!Array.isArray(values)) return display(value); const tags = values.map(item => typeof item === 'string' ? item : item?.name || item?.tag || JSON.stringify(item)).filter(Boolean); return tags.length ? `<span class="inline-tags">${tags.map(tag => `<span class="tag tag-compact">${esc(tag)}</span>`).join('')}</span>` : '<span class="dash">—</span>' }
function accountMetric(value, rate = false) { if (value === null || value === undefined || value === '') return '<span class="dash">—</span>'; const exact = String(value); const textValue = rate ? String(Number(value).toFixed(4)).replace(/0+$/u, '').replace(/\.$/u, '') : formatMetric(value); return `<span class="metric-value" title="${esc(exact)}">${esc(textValue)}</span>` }
function accountDate(value) { if (value === null || value === undefined || value === '') return '<span class="dash">—</span>'; return `<time title="${esc(value)}">${esc(formatDateTime(value))}</time>` }
function accountCell(row, column) { if (column.key === 'publisher') { const avatar = safeUrl(row.profile_avatar || row.avatar); const name = row.wx_name || '未命名账号'; return `<div class="account-publisher">${avatar ? `<img src="${esc(avatar)}" alt="" loading="lazy">` : '<span class="avatar-placeholder">号</span>'}<div><button class="link-button account-name" data-account-name data-account-id="${esc(row.account_id)}">${esc(name)}</button><span class="account-biz">${display(row.wx_biz)}</span></div></div>` } if (column.key === 'actions') return `<div class="account-actions"><button class="button button-small button-approve" data-quick-decision="1" data-account-id="${esc(row.account_id)}" ${writeDisabled() || state.accountBusyIds.has(Number(row.account_id)) ? 'disabled' : ''}>通过</button><button class="button button-small button-filter" data-quick-decision="2" data-account-id="${esc(row.account_id)}" ${writeDisabled() || state.accountBusyIds.has(Number(row.account_id)) ? 'disabled' : ''}>过滤</button></div>`; if (column.key === 'account.verify') return row.verify ? `<span class="verify-text" title="${esc(row.verify)}">已认证</span>` : '<span class="dash">—</span>'; if (column.key === 'account.decision_status') return statusPill(row.decision_status); if (column.key === 'profile.type_region') { const type = row.profile_wx_type ?? row.wx_type; const region = row.profile_region ?? row.region; return type || region ? `${display(type)} <span class="muted">/</span> ${display(region)}` : '<span class="dash">—</span>' } const value = accountFieldValue(row, column); if (['tags', 'manual_tags'].includes(column.field)) return accountTags(value); if (column.field === 'avatar') { const url = safeUrl(value); return url ? `<img class="table-avatar" src="${esc(url)}" alt="" loading="lazy">` : '<span class="dash">—</span>' } if (column.field === 'decision_status') return statusPill(value); if (column.field === 'decision_source') return value === 'manual' ? '人工' : value === 'auto' ? '自动' : display(value); if (['updated_at', 'last_pub_time', 'collected_at'].includes(column.field)) return accountDate(value); if (column.numeric || ['account_id', 'pub_count', 'active_days', 'read_avg', 'read_median', 'read_max', 'burst_count', 'look_avg', 'look_median', 'look_max', 'like_avg', 'like_median', 'like_max', 'share_avg', 'share_median', 'share_max', 'comment_avg', 'comment_median', 'comment_max', 'ori_count'].includes(column.field)) return accountMetric(value, column.rate); return display(value) }
function optionalAccountColumn(source, field) { const key = `${source}.${field}`; const sortKey = source === 'account' ? ['updated_at', 'read_median', 'read_max'].includes(field) ? field === 'read_median' || field === 'read_max' ? `account.${field}` : field : null : ['last_pub_time', 'collected_at', 'pub_count', 'active_days', 'read_avg', 'read_median', 'read_max', 'burst_count', 'burst_rate', 'look_avg', 'look_median', 'look_max', 'like_avg', 'like_median', 'like_max', 'share_avg', 'share_median', 'share_max', 'comment_avg', 'comment_median', 'comment_max', 'ori_count'].includes(field) ? `profile.${field}` : null; return { key, label: accountColumnLabel({ source, field }), source, field, sortKey, numeric: source === 'account' ? ['account_id', 'read_median', 'read_max'].includes(field) : ['account_id', 'pub_count', 'active_days', 'read_avg', 'read_median', 'read_max', 'burst_count', 'burst_rate', 'look_avg', 'look_median', 'look_max', 'like_avg', 'like_median', 'like_max', 'share_avg', 'share_median', 'share_max', 'comment_avg', 'comment_median', 'comment_max', 'ori_count'].includes(field), rate: field === 'burst_rate' }
}
function accountTableColumns() { const fixed = [...ACCOUNT_FIXED_COLUMNS]; const fixedKeys = new Set(fixed.map(column => column.key)); const optional = readAccountColumnPreference().map(key => { const [source, field] = key.split('.'); return optionalAccountColumn(source, field) }).filter(column => !fixedKeys.has(column.key)); return [...fixed.slice(0, -1), ...optional, fixed.at(-1)] }
function accountSortLabel(column) { if (!column.sortKey) return esc(column.label); const active = (state.query.sort || 'updated_at') === column.sortKey; const direction = state.query.sortDir || 'desc'; return `<button class="sort-button" type="button" data-account-sort="${esc(column.sortKey)}" aria-label="按${esc(column.label)}排序" aria-sort="${active ? direction : 'none'}">${esc(column.label)}<span class="sort-indicator">${active ? direction === 'asc' ? '↑' : '↓' : '↕'}</span></button>` }
function accountPager(result) { const hasNext = result.total === null || result.total === undefined ? result.items.length === result.pageSize : result.page * result.pageSize < result.total; return `<div class="table-footer"><span>${pageLabel({ page: result.page, pageSize: result.pageSize, total: result.total, loadedCount: result.items.length, hasNext })}</span><div class="pager"><button class="button button-ghost button-small" data-account-page="${Math.max(1, result.page - 1)}" ${result.page <= 1 ? 'disabled' : ''}>上一页</button><span>第 ${result.page} 页</span><button class="button button-ghost button-small" data-account-page="${result.page + 1}" ${!hasNext ? 'disabled' : ''}>下一页</button><select data-account-page-size aria-label="账号每页条数"><option ${result.pageSize === 50 ? 'selected' : ''}>50</option><option ${result.pageSize === 100 ? 'selected' : ''}>100</option></select></div></div>` }
async function loadAccounts() { const host = $('#accounts-data'); if (!host) return; state.accountRequestController?.abort(); const controller = new AbortController(); state.accountRequestController = controller; const columns = accountQueryColumns(); const query = { ...state.query, ...columns, page: state.page, pageSize: state.pageSize }; try { const result = await api.get(`/api/accounts?${queryString(query)}`, { key: 'accounts:list', signal: controller.signal, cache: false }); state.accountRows = Array.isArray(result.items) ? result.items : []; state.accountResult = { ...result, items: state.accountRows }; state.selectedAccountIds.clear(); state.accountFocusedIndex = -1; renderAccountTable() } catch (error) { if (error?.name === 'AbortError') return; host.innerHTML = `<div class="error-box">${esc(errorText(error))}</div>`; updateAccountBulkBar(); apiError(error) } }
function renderAccountTable() { const host = $('#accounts-data'); if (!host || !state.accountResult) return; const result = { ...state.accountResult, items: state.accountRows }; const columns = accountTableColumns(); host.innerHTML = result.items.length ? `<div class="table-scroll account-table-scroll"><table class="account-table"><thead><tr><th class="sticky-select"><input data-account-select-all type="checkbox" aria-label="全选当前页" ${result.items.length && result.items.every(row => state.selectedAccountIds.has(Number(row.account_id))) ? 'checked' : ''}></th>${columns.map(column => `<th class="${column.className || ''} ${column.numeric ? 'numeric-head' : ''}">${accountSortLabel(column)}</th>`).join('')}</tr></thead><tbody>${result.items.map((row, index) => `<tr data-account-row data-account-id="${esc(row.account_id)}" class="${index === state.accountFocusedIndex ? 'keyboard-focus' : ''}"><td class="sticky-select"><input type="checkbox" data-account-select value="${esc(row.account_id)}" aria-label="选择${esc(row.wx_name || row.wx_biz || row.account_id)}" ${state.selectedAccountIds.has(Number(row.account_id)) ? 'checked' : ''}></td>${columns.map(column => `<td class="${column.className || ''} ${column.numeric ? 'numeric-cell' : ''}">${accountCell(row, column)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${accountPager(result)}` : '<div class="empty">暂无账号，或筛选条件没有命中。</div>'; bindAccountTableEvents(); updateAccountBulkBar() }
function bindAccountTableEvents() { const host = $('#accounts-data'); host.querySelector('[data-account-select-all]')?.addEventListener('change', event => { host.querySelectorAll('[data-account-select]').forEach(node => { node.checked = event.target.checked; const id = Number(node.value); if (event.target.checked) state.selectedAccountIds.add(id); else state.selectedAccountIds.delete(id) }); updateAccountBulkBar() }); host.querySelectorAll('[data-account-select]').forEach(node => node.addEventListener('change', () => { const id = Number(node.value); if (node.checked) state.selectedAccountIds.add(id); else state.selectedAccountIds.delete(id); updateAccountBulkBar() })); host.querySelectorAll('[data-account-sort]').forEach(node => node.addEventListener('click', () => cycleAccountSort(node.dataset.accountSort))); host.querySelectorAll('[data-account-name]').forEach(node => node.addEventListener('click', event => { event.stopPropagation(); openAccount(node.dataset.accountId) })); host.querySelectorAll('[data-quick-decision]').forEach(node => node.addEventListener('click', event => { event.stopPropagation(); quickAccountDecision(Number(node.dataset.accountId), Number(node.dataset.quickDecision)) })); host.querySelectorAll('[data-account-row]').forEach(node => node.addEventListener('click', event => { if (event.target.closest('button,input,select,a')) return; state.accountFocusedIndex = [...host.querySelectorAll('[data-account-row]')].indexOf(node); node.classList.add('keyboard-focus'); openAccount(node.dataset.accountId) })); host.querySelectorAll('[data-account-page]').forEach(node => node.addEventListener('click', () => { state.page = Number(node.dataset.accountPage); state.selectedAccountIds.clear(); state.accountFocusedIndex = -1; loadAccounts() })); host.querySelector('[data-account-page-size]')?.addEventListener('change', event => { state.pageSize = Number(event.target.value); state.page = 1; state.selectedAccountIds.clear(); rememberViewState(); loadAccounts() }) }
function cycleAccountSort(sortKey) { const active = state.query.sort || 'updated_at'; const direction = state.query.sortDir || 'desc'; if (active !== sortKey) { state.query = { ...state.query, sort: sortKey, sortDir: 'asc' } } else if (direction === 'asc') { state.query = { ...state.query, sort: sortKey, sortDir: 'desc' } } else { const next = { ...state.query }; delete next.sort; delete next.sortDir; state.query = next } state.page = 1; state.selectedAccountIds.clear(); api.invalidate('accounts:list'); loadAccounts() }
function updateAccountBulkBar() { const bar = $('#account-bulk-bar'); if (!bar) return; const selected = [...state.selectedAccountIds].filter(id => state.accountRows.some(row => Number(row.account_id) === id)); state.selectedAccountIds = new Set(selected); if (!selected.length) { bar.classList.add('hidden'); bar.replaceChildren(); return } bar.classList.remove('hidden'); bar.innerHTML = `<span>已选择 <strong>${selected.length}</strong> 个账号</span><button class="button button-small button-approve" data-bulk-decision="1" ${writeDisabled() ? 'disabled' : ''}>批量通过</button><button class="button button-small button-filter" data-bulk-decision="2" ${writeDisabled() ? 'disabled' : ''}>批量过滤</button><button class="button button-ghost button-small" data-clear-account-selection>取消选择</button>`; bar.querySelectorAll('[data-bulk-decision]').forEach(node => node.addEventListener('click', () => bulkAccountDecision(Number(node.dataset.bulkDecision)))); bar.querySelector('[data-clear-account-selection]').addEventListener('click', () => { state.selectedAccountIds.clear(); renderAccountTable() }) }

function decisionSnapshot(row) { return { decision_status: row.decision_status ?? null, decision_source: row.decision_source ?? null, filter_rule_id: row.filter_rule_id ?? null, updated_at: row.updated_at } }
function mergeAccountDetail(row, item) { const merged = { ...row, ...item }; if (item?.profile) for (const [field, value] of Object.entries(item.profile)) { merged[`profile_${field}`] = value; if (!['read_median', 'read_max'].includes(field)) merged[field] = value } return merged }
function accountStatusMatches(row) { const status = state.query.status; return status === undefined || status === null || status === '' || Number(row.decision_status) === Number(status) }
function accountRowAfterDecision(row, item, status) { const updated = mergeAccountDetail(row, item || {}); updated.decision_status = status; updated.decision_source = 'manual'; updated.filter_rule_id = null; return updated }
function replaceAccountRow(updated, previousStatus) { const beforeLength = state.accountRows.length; state.accountRows = state.accountRows.map(row => Number(row.account_id) === Number(updated.account_id) ? updated : row).filter(accountStatusMatches); if (state.accountResult && state.accountResult.total !== null && state.accountResult.total !== undefined && state.accountRows.length < beforeLength) state.accountResult.total = Math.max(0, state.accountResult.total - 1); state.accountResult = { ...(state.accountResult || {}), items: state.accountRows, page: state.page, pageSize: state.pageSize }; state.selectedAccountIds.delete(Number(updated.account_id)); if (previousStatus !== undefined && previousStatus !== updated.decision_status) state.accountFocusedIndex = Math.min(state.accountFocusedIndex, state.accountRows.length - 1) }
async function quickAccountDecision(id, status) { if (writeDisabled()) return; const row = state.accountRows.find(item => Number(item.account_id) === id); if (!row || state.accountBusyIds.has(id)) return; const previous = decisionSnapshot(row); state.accountBusyIds.add(id); renderAccountTable(); try { const result = await api.mutate(`/api/accounts/${encodeURIComponent(id)}/decision`, { method: 'PATCH', body: { decision_status: status, expected_decision: previous, expected_decision_status: previous.decision_status, expected_updated_at: previous.updated_at } }); const updated = accountRowAfterDecision(row, result.item, status); replaceAccountRow(updated, previous.decision_status); renderAccountTable(); const current = decisionSnapshot(updated); const token = Symbol('account-undo'); state.accountUndo = { token, id, previous, current }; setTimeout(() => { if (state.accountUndo?.token === token) state.accountUndo = null }, 5000); toast(status === 1 ? '账号已通过' : '账号已过滤', { actionLabel: '撤销', onAction: () => undoAccountDecision(id, previous, current) }) } catch (error) { state.accountBusyIds.delete(id); renderAccountTable(); apiError(error) } finally { state.accountBusyIds.delete(id); renderAccountTable() } }
async function undoAccountDecision(id, previous, current) { if (writeDisabled()) return; const row = state.accountRows.find(item => Number(item.account_id) === id); state.accountBusyIds.add(id); if (row) renderAccountTable(); try { const result = await api.mutate(`/api/accounts/${encodeURIComponent(id)}/decision`, { method: 'PATCH', body: { restore_decision: { decision_status: previous.decision_status, decision_source: previous.decision_source, filter_rule_id: previous.filter_rule_id }, expected_decision: current, expected_updated_at: current.updated_at } }); if (row) { const updated = mergeAccountDetail(row, result.item); updated.decision_status = previous.decision_status; updated.decision_source = previous.decision_source; updated.filter_rule_id = previous.filter_rule_id; replaceAccountRow(updated, row.decision_status); state.accountUndo = null; renderAccountTable() } else { state.accountUndo = null; api.invalidate('accounts:list'); await loadAccounts() } toast('已撤销本次审核') } catch (error) { apiError(error) } finally { state.accountBusyIds.delete(id); renderAccountTable() } }
async function bulkAccountDecision(status) { const rows = state.accountRows.filter(row => state.selectedAccountIds.has(Number(row.account_id))); if (!rows.length || writeDisabled()) return; const label = status === 1 ? '通过' : '过滤'; if (!confirmAction(`确认将 ${rows.length} 个账号标记为${label}？`)) return; const ids = rows.map(row => Number(row.account_id)); const expected = Object.fromEntries(rows.map(row => [row.account_id, decisionSnapshot(row)])); try { const result = await api.mutate('/api/accounts/bulk-status', { method: 'POST', body: { ids, decision_status: status, expected_decisions: expected } }); const succeeded = new Set((result.succeededIds || []).map(Number)); state.accountRows = state.accountRows.map(row => succeeded.has(Number(row.account_id)) ? { ...row, decision_status: status, decision_source: 'manual', filter_rule_id: null } : row).filter(accountStatusMatches); if (state.accountResult && state.accountResult.total !== null && state.accountResult.total !== undefined) state.accountResult.total = Math.max(0, state.accountResult.total - rows.filter(row => succeeded.has(Number(row.account_id)) && !accountStatusMatches({ ...row, decision_status: status })).length); state.selectedAccountIds.clear(); state.accountResult = { ...(state.accountResult || {}), items: state.accountRows }; renderAccountTable(); toast(`批量${label}完成：成功 ${result.count || 0} 个，失败 ${result.failed?.length || 0} 个`) } catch (error) { apiError(error) } }
function detailValue(value) { return display(value) }
function detailMetric(value, rate = false) { return accountMetric(value, rate) }
function detailSection(title, fields) { return `<section class="detail-section"><h3>${esc(title)}</h3><div class="detail-grid">${fields.map(([label, value, className = '']) => `<div class="detail-item ${className}"><span>${esc(label)}</span><strong>${value}</strong></div>`).join('')}</div></section>` }
function detailProfileMetric(profile, field) { return detailMetric(profile?.[field]) }
function accountDetailMarkup(item) { const profile = item.profile; const avatar = safeUrl(profile?.avatar); const tags = accountTags(profile?.tags); const manualTags = accountTags(profile?.manual_tags); return `<div class="drawer-head"><div class="drawer-title-with-avatar">${avatar ? `<img class="drawer-avatar" src="${esc(avatar)}" alt="" loading="lazy">` : '<span class="avatar-placeholder drawer-avatar">号</span>'}<div><p class="eyebrow">ACCOUNT DETAIL</p><h2>${detailValue(item.wx_name || '未命名账号')}</h2><p class="muted">${detailValue(item.wx_biz)}</p></div></div><button class="drawer-close" data-close-drawer aria-label="关闭详情">×</button></div><div class="drawer-quick-actions"><button class="button button-small button-approve" data-drawer-decision="1" ${writeDisabled() ? 'disabled' : ''}>通过</button><button class="button button-small button-filter" data-drawer-decision="2" ${writeDisabled() ? 'disabled' : ''}>过滤</button>${statusPill(item.decision_status)}</div>${detailSection('基础信息', [['账号 account_id', detailValue(item.account_id)], ['详情 account_id', detailValue(profile?.account_id)], ['公众号名', detailValue(item.wx_name)], ['wx_biz', detailValue(item.wx_biz)], ['wx_user', detailValue(profile?.wx_user)], ['认证', detailValue(item.verify)], ['简介', detailValue(item.description), 'detail-wide'], ['类型', detailValue(profile?.wx_type)], ['地区', detailValue(profile?.region)], ['tags', tags, 'detail-wide'], ['manual_tags', manualTags, 'detail-wide']])}${detailSection('审核', [['decision_status', statusPill(item.decision_status)], ['decision_source', item.decision_source === 'manual' ? '人工' : item.decision_source === 'auto' ? '自动' : detailValue(item.decision_source)], ['filter_rule_id', detailValue(item.filter_rule_id)], ['updated_at', accountDate(item.updated_at)]])}${detailSection('发文', [['last_pub_time', accountDate(profile?.last_pub_time)], ['pub_count', detailMetric(profile?.pub_count)], ['active_days', detailMetric(profile?.active_days)], ['ori_count', detailMetric(profile?.ori_count)], ['collected_at', accountDate(profile?.collected_at)]])}${detailSection('阅读', [['read_avg', detailProfileMetric(profile, 'read_avg')], ['详情中位阅读', detailProfileMetric(profile, 'read_median')], ['详情最高阅读', detailProfileMetric(profile, 'read_max')], ['账号中位阅读', detailMetric(item.read_median)], ['账号最高阅读', detailMetric(item.read_max)]])}${detailSection('爆文', [['burst_count', detailMetric(profile?.burst_count)], ['burst_rate', detailMetric(profile?.burst_rate, true)]])}${detailSection('在看', [['look_avg', detailMetric(profile?.look_avg)], ['look_median', detailMetric(profile?.look_median)], ['look_max', detailMetric(profile?.look_max)]])}${detailSection('点赞', [['like_avg', detailMetric(profile?.like_avg)], ['like_median', detailMetric(profile?.like_median)], ['like_max', detailMetric(profile?.like_max)]])}${detailSection('分享', [['share_avg', detailMetric(profile?.share_avg)], ['share_median', detailMetric(profile?.share_median)], ['share_max', detailMetric(profile?.share_max)]])}${detailSection('留言', [['comment_avg', detailMetric(profile?.comment_avg)], ['comment_median', detailMetric(profile?.comment_median)], ['comment_max', detailMetric(profile?.comment_max)]])}${writeDisabled() ? '' : `<form class="form-stack detail-tags-form" id="account-tags-form"><div class="field"><label>manual_tags（逗号分隔）</label><input name="manual_tags" value="${esc(Array.isArray(profile?.manual_tags) ? profile.manual_tags.join(', ') : '')}" placeholder="人工标签"></div><div class="form-actions"><button class="button button-small" type="submit">保存人工标签</button></div></form>`}` }
async function openAccount(id) { openDrawer('<div class="loading">加载详情…</div>'); try { const result = await api.get(`/api/accounts/${encodeURIComponent(id)}`, { key: `account:${id}`, cache: false }); const item = result.item; const profile = item.profile; $('#drawer').innerHTML = accountDetailMarkup(item); $('#drawer').querySelectorAll('[data-close-drawer]').forEach(node => node.addEventListener('click', closeDrawer)); $('#drawer').querySelectorAll('[data-drawer-decision]').forEach(node => node.addEventListener('click', () => { closeDrawer(); quickAccountDecision(Number(item.account_id), Number(node.dataset.drawerDecision)) })); $('#account-tags-form')?.addEventListener('submit', event => saveAccountTags(event, item, profile)) } catch (error) { $('#drawer').innerHTML = `<div class="error-box">${esc(errorText(error))}</div>`; apiError(error) } }
async function saveAccountTags(event, item, profile) { event.preventDefault(); const tags = event.currentTarget.elements.manual_tags.value.split(/[，,\n]/u).map(value => value.trim()).filter(Boolean); try { await api.mutate(`/api/accounts/${encodeURIComponent(item.account_id)}/tags`, { method: 'PATCH', body: { manual_tags: tags, expected_manual_tags: Array.isArray(profile?.manual_tags) ? profile.manual_tags : null } }); toast('人工标签已保存'); closeDrawer(); api.invalidate('accounts:list'); loadAccounts() } catch (error) { apiError(error) } }
function moveAccountFocus(delta) { if (state.view !== 'accounts' || !state.accountRows.length) return; const next = state.accountFocusedIndex < 0 ? delta > 0 ? 0 : state.accountRows.length - 1 : Math.max(0, Math.min(state.accountRows.length - 1, state.accountFocusedIndex + delta)); state.accountFocusedIndex = next; renderAccountTable(); document.querySelector(`[data-account-row][data-account-id="${CSS.escape(String(state.accountRows[next].account_id))}"]`)?.scrollIntoView({ block: 'nearest' }) }
function accountKeyboardTarget(target) { return target?.matches?.('input,select,textarea,button,[contenteditable="true"]') || target?.closest?.('.drawer.open') }
function handleAccountKeyboard(event) { if (state.view !== 'accounts' || accountKeyboardTarget(event.target) || $('#drawer')?.classList.contains('open')) return; if (event.key === 'j' || event.key === 'J' || event.key === 'ArrowDown') { event.preventDefault(); moveAccountFocus(1) } else if (event.key === 'k' || event.key === 'K' || event.key === 'ArrowUp') { event.preventDefault(); moveAccountFocus(-1) } else if (event.key === 'Enter' && state.accountRows[state.accountFocusedIndex]) { event.preventDefault(); openAccount(state.accountRows[state.accountFocusedIndex].account_id) } else if ((event.key === '1' || event.key === '2') && state.accountRows[state.accountFocusedIndex]) { event.preventDefault(); quickAccountDecision(Number(state.accountRows[state.accountFocusedIndex].account_id), Number(event.key)) } }

async function renderArticles() { $('#page-title').textContent = '文章管理'; $('#page-root').innerHTML = `<div class="page-intro"><div><h2>文章管理</h2><p>按服务端交集筛选；is_original 的未知值保持为“未知”。</p></div></div>${writeHint()}<form class="filters" id="article-filter"><div class="field"><label>标题关键词</label><input name="keyword" value="${esc(state.query.keyword || '')}" placeholder="标题包含"></div><div class="field"><label>账号 ID</label><input name="accountId" type="number" min="1" value="${displayInput(state.query.accountId)}"></div><div class="field"><label>原创</label><select name="isOriginal"><option value="">全部</option><option value="true" ${state.query.isOriginal === 'true' ? 'selected' : ''}>原创</option><option value="false" ${state.query.isOriginal === 'false' ? 'selected' : ''}>非原创</option><option value="unknown" ${state.query.isOriginal === 'unknown' ? 'selected' : ''}>未知</option></select></div><div class="field"><label>开始日 UTC</label><input name="from" type="date" value="${displayInput(state.query.from)}"></div><div class="field"><label>结束日 UTC</label><input name="to" type="date" value="${displayInput(state.query.to)}"></div><div class="field"><label>阅读最小</label><input name="readMin" type="number" min="0" value="${displayInput(state.query.readMin)}"></div><div class="field"><label>阅读最大</label><input name="readMax" type="number" min="0" value="${displayInput(state.query.readMax)}"></div><button class="button" type="submit">查询</button></form><div class="table-card" id="articles-data"><div class="loading">加载文章列表…</div></div>`; $('#article-filter').addEventListener('submit', event => { event.preventDefault(); state.query = Object.fromEntries(new FormData(event.currentTarget)); state.page = 1; loadArticles() }); loadArticles() }
async function loadArticles() { const host = $('#articles-data'); if (!host) return; try { const result = await api.get(`/api/articles?${queryString({ ...state.query, page: state.page, pageSize: state.pageSize })}`, { key: 'articles:list' }); host.innerHTML = result.items.length ? `<div class="table-scroll"><table><thead><tr><th><input data-select-all type="checkbox" aria-label="选择本页文章"></th><th>标题</th><th>账号</th><th>发布时间 UTC</th><th>阅读</th><th>点赞</th><th>评论</th><th>原创</th><th>操作</th></tr></thead><tbody>${result.items.map(row => `<tr><td><input type="checkbox" data-article-select value="${esc(row.id)}" data-updated="${esc(row.updated_at || '')}" aria-label="选择文章"></td><td>${display(row.title)}</td><td>${display(row.publisher)}</td><td>${display(row.published_at)}</td><td>${display(row.read_num)}</td><td>${display(row.like_num)}</td><td>${display(row.comment_num)}</td><td>${row.is_original === null ? '<span class="pill">未知</span>' : row.is_original ? '<span class="pill pill-green">原创</span>' : '<span class="pill">非原创</span>'}</td><td><button class="button button-danger button-small" data-delete-article="${esc(row.id)}" data-updated="${esc(row.updated_at || '')}" ${writeDisabled() ? 'disabled' : ''}>删除</button></td></tr>`).join('')}</tbody></table></div>${pager(result, 'articles')}` : '<div class="empty">暂无文章。</div>'; host.querySelector('[data-select-all]')?.addEventListener('change', event => host.querySelectorAll('[data-article-select]').forEach(node => { node.checked = event.target.checked })); host.querySelectorAll('[data-delete-article]').forEach(node => node.addEventListener('click', () => deleteArticles([{ id: Number(node.dataset.deleteArticle), updated: node.dataset.updated }]))); bindPager('articles', loadArticles) } catch (error) { host.innerHTML = `<div class="error-box">${esc(errorText(error))}</div>`; apiError(error) } }
async function deleteArticles(items) { if (!items.length || !confirmAction(`确认删除 ${items.length} 篇文章？热词 article_keys 不会被自动清理。`)) return; try { const body = { ids: items.map(item => item.id), expected_updated_atById: Object.fromEntries(items.map(item => [item.id, item.updated])) }; const result = await api.mutate('/api/articles', { method: 'DELETE', body }); toast(result.failed?.length ? `已删除 ${result.count} 条，${result.failed.length} 条失败` : `已删除 ${result.count} 条`); api.invalidate('articles:list'); loadArticles() } catch (error) { apiError(error) } }

async function renderRules() { $('#page-title').textContent = '过滤规则'; $('#page-root').innerHTML = `<div class="page-intro"><div><h2>过滤规则</h2><p>按作用域、字段、运算符分组；命中数是规则 hit_count 之和，不代表唯一账号数。</p></div><button class="button button-ghost" id="reload-rules">刷新规则</button></div>${writeHint()}<div id="rules-data"><div class="loading">加载完整规则分组…</div></div>`; $('#reload-rules').addEventListener('click', loadRules); loadRules() }
async function loadRulesLegacy() { const host = $('#rules-data'); try { const result = await api.get('/api/rules/groups', { key: 'rules:groups' }); host.innerHTML = result.groups.length ? `<div class="grid">${result.groups.map(group => `<article class="card rule-card"><div class="card-head"><div><h3>${esc(group.label || `${group.scope}.${group.field_name}`)}</h3><div class="card-meta">${esc(group.scope)} · ${esc(group.field_name)} · ${esc(group.operator)}<br>${group.rows.length} 条规则 · 命中和 ${group.hit_count}</div></div><span class="pill ${group.enabled_state === 'enabled' ? 'pill-green' : group.enabled_state === 'mixed' ? 'pill-amber' : ''}">${group.enabled_state === 'mixed' ? '混合' : group.enabled ? '全启用' : '全停用'}</span></div><div class="tag-list">${group.rows.map(row => `<span class="tag" title="${esc(row.remark || '')}">${esc(row.value_text ?? row.value_number)}${row.enabled ? '' : ' · 停用'}</span>`).join('')}</div><button class="button button-small button-ghost" data-rule-group="${esc(group.key)}" ${writeDisabled() ? 'disabled' : ''}>查看配置快照</button></article>`).join('')}</div>` : '<div class="empty card">暂无规则配置。</div>'; host.querySelectorAll('[data-rule-group]').forEach(node => node.addEventListener('click', () => toast('规则分组保存需要携带原始行快照，当前请在详情流程中操作。'))) } catch (error) { host.innerHTML = `<div class="error-box">${esc(errorText(error))}</div>`; apiError(error) } }

function ruleEntryMarkup(group, row = {}) {
  const numeric = group.type === 'number'
  const value = row.value_text ?? row.value_number ?? ''
  const idAttribute = row.id === undefined ? '' : ` data-id="${esc(row.id)}"`
  return `<div class="rule-entry" data-rule-entry${idAttribute}><div class="field"><label>${numeric ? '阈值' : '规则值'}</label><input name="value" type="${numeric ? 'number' : 'text'}" ${numeric ? 'step="any"' : ''} value="${esc(value)}" required></div><label class="check-field"><input name="enabled" type="checkbox" ${row.enabled === false ? '' : 'checked'}>启用</label><div class="field"><label>备注</label><input name="remark" value="${esc(row.remark || '')}" maxlength="255"></div><button class="button button-danger button-small" type="button" data-remove-rule>移除</button></div>`
}

function bindRuleEntryControls(container) {
  container.querySelectorAll('[data-remove-rule]').forEach(button => button.addEventListener('click', () => button.closest('[data-rule-entry]')?.remove()))
}

function openRuleGroup(group) {
  openDrawer(`<div class="drawer-head"><div><p class="eyebrow">RULE GROUP</p><h2>${esc(group.label)}</h2><p class="muted">${esc(group.scope)} · ${esc(group.field_name)} · ${esc(group.operator)}</p></div><button class="drawer-close" data-close-drawer aria-label="关闭规则编辑">×</button></div><div class="notice">保存采用原始行快照 + 逐行 CAS；部分成功时会保留当前草稿，其他人后来新增的 Tag 不会被删除。</div><form class="form-stack" id="rule-group-edit"><div id="rule-entries" class="rule-entries">${(group.rows || []).map(row => ruleEntryMarkup(group, row)).join('') || '<div class="empty">当前分组还没有规则。</div>'}</div><div class="form-actions"><button class="button button-ghost" type="button" id="add-rule-entry">新增一行</button><span class="spacer"></span><button class="button button-ghost" type="button" data-close-drawer>取消</button><button class="button" type="submit" ${writeDisabled() ? 'disabled' : ''}>保存分组</button></div></form>`)
  const drawer = $('#drawer')
  drawer.querySelectorAll('[data-close-drawer]').forEach(node => node.addEventListener('click', closeDrawer))
  bindRuleEntryControls(drawer)
  $('#add-rule-entry').addEventListener('click', () => { const list = $('#rule-entries'); list.querySelector('.empty')?.remove(); list.insertAdjacentHTML('beforeend', ruleEntryMarkup(group)); bindRuleEntryControls(list) })
  $('#rule-group-edit').addEventListener('submit', event => saveRuleGroup(event, group))
}

async function saveRuleGroup(event, group) {
  event.preventDefault()
  const form = event.currentTarget
  const submit = form.querySelector('button[type="submit"]')
  const entries = [...form.querySelectorAll('[data-rule-entry]')].map(node => {
    const value = node.querySelector('[name="value"]').value.trim()
    const entry = { enabled: node.querySelector('[name="enabled"]').checked, remark: node.querySelector('[name="remark"]').value }
    if (node.dataset.id) entry.id = Number(node.dataset.id)
    entry.value = group.type === 'number' ? Number(value) : value
    return entry
  })
  submit.disabled = true
  try {
    const result = await api.mutate('/api/rules/groups/save', { body: { groupKey: group.key, original_rows: group.rows, draft: { entries } } })
    api.invalidate('rules:groups')
    if (result.status === 'success') { closeDrawer(); toast('配置已保存；使用数据库规则的下一次执行将读取新配置'); loadRules() } else toast('规则分组部分成功，请核对失败项并重试')
  } catch (error) { apiError(error) } finally { if (submit.isConnected) submit.disabled = writeDisabled() }
}

async function loadRules() {
  const host = $('#rules-data')
  try {
    const result = await api.get('/api/rules/groups', { key: 'rules:groups' })
    const textGroups = result.groups.filter(group => group.type === 'text')
    const numberGroups = result.groups.filter(group => group.type === 'number')
    const statusLabel = group => group.enabled_state === 'mixed' ? '混合' : group.enabled_state === 'empty' ? '未配置' : group.enabled ? '全启用' : '全停用'
    const textCards = textGroups.map(group => `<article class="card rule-card"><div class="card-head"><div><h3>${esc(group.label)}</h3><div class="card-meta">${esc(group.scope)} · ${esc(group.field_name)} · ${esc(group.operator)}<br>${group.rows.length} 条规则 · 命中和 ${group.hit_count}</div></div><span class="pill ${group.enabled_state === 'enabled' ? 'pill-green' : group.enabled_state === 'mixed' ? 'pill-amber' : ''}">${statusLabel(group)}</span></div><div class="tag-list">${group.rows.length ? group.rows.map(row => `<span class="tag" title="${esc(row.remark || '')}">${esc(row.value_text ?? row.value_number)}${row.enabled ? '' : ' · 停用'}</span>`).join('') : '<span class="muted">暂无规则</span>'}</div><button class="button button-small button-ghost" data-rule-group="${esc(group.key)}" ${writeDisabled() ? 'disabled' : ''}>${group.rows.length ? '编辑分组' : '新增规则'}</button></article>`).join('')
    const numberTable = numberGroups.length ? `<div class="table-card"><div class="section-label">数值规则</div><div class="table-scroll"><table><thead><tr><th>规则</th><th>字段 / 运算</th><th>条数</th><th>命中和</th><th>状态</th><th>操作</th></tr></thead><tbody>${numberGroups.map(group => `<tr><td>${esc(group.label)}</td><td>${esc(group.field_name)} · ${esc(group.operator)}</td><td>${group.rows.length}</td><td>${group.hit_count}</td><td>${statusLabel(group)}</td><td><button class="button button-small button-ghost" data-rule-group="${esc(group.key)}" ${writeDisabled() ? 'disabled' : ''}>编辑</button></td></tr>`).join('')}</tbody></table></div></div>` : ''
    host.innerHTML = `${textCards ? `<div class="grid">${textCards}</div>` : ''}${numberTable || '<div class="empty card">暂无数值规则。</div>'}`
    host.querySelectorAll('[data-rule-group]').forEach(node => node.addEventListener('click', () => openRuleGroup(result.groups.find(group => group.key === node.dataset.ruleGroup))))
  } catch (error) { host.innerHTML = `<div class="error-box">${esc(errorText(error))}</div>`; apiError(error) }
}

async function renderHotwords() { $('#page-title').textContent = '热词管理'; $('#page-root').innerHTML = `<div class="page-intro"><div><h2>热词管理</h2><p>article_keys 是不透明来源键，不是 articles.id；合并为非原子操作。</p></div><button id="hotword-merge" class="button" disabled>合并选中项</button></div>${writeHint()}<form class="filters" id="hotword-filter"><div class="field"><label>标准词</label><input name="keyword" value="${esc(state.query.keyword || '')}" placeholder="搜索标准词"></div><div class="field"><label>日期</label><input name="statDate" type="date" value="${displayInput(state.query.statDate)}"></div><button class="button" type="submit">查询</button></form><div class="table-card" id="hotwords-data"><div class="loading">加载热词列表…</div></div>`; $('#hotword-filter').addEventListener('submit', event => { event.preventDefault(); state.query = Object.fromEntries(new FormData(event.currentTarget)); state.page = 1; loadHotwords() }); loadHotwords() }
async function loadHotwordsLegacy() { const host = $('#hotwords-data'); try { const result = await api.get(`/api/hotwords?${queryString({ ...state.query, page: state.page, pageSize: state.pageSize })}`, { key: 'hotwords:list' }); host.innerHTML = result.items.length ? `<div class="table-scroll"><table><thead><tr><th></th><th>标准词</th><th>别名</th><th>日期</th><th>文章数</th><th>代表链接</th></tr></thead><tbody>${result.items.map(row => { const url = safeUrl(row.article_url); return `<tr><td><input type="checkbox" data-hotword-select value="${esc(row.id)}" aria-label="选择热词"></td><td>${display(row.hotword)}</td><td>${display((row.aliases || []).join('、'))}</td><td>${display(row.stat_date)}</td><td>${display(row.article_count)}</td><td>${url ? `<a href="${esc(url)}" target="_blank" rel="noreferrer">打开</a>` : '<span class="dash">—</span>'}</td></tr>` }).join('')}</tbody></table></div>${pager(result, 'hotwords')}` : '<div class="empty">暂无热词。</div>'; host.querySelectorAll('[data-hotword-select]').forEach(node => node.addEventListener('change', updateMergeButton)); bindPager('hotwords', loadHotwords) } catch (error) { host.innerHTML = `<div class="error-box">${esc(errorText(error))}</div>`; apiError(error) } }
async function loadHotwords() {
  const host = $('#hotwords-data')
  try {
    const result = await api.get(`/api/hotwords?${queryString({ ...state.query, page: state.page, pageSize: state.pageSize })}`, { key: 'hotwords:list' })
    host.innerHTML = result.items.length ? `<div class="table-scroll"><table><thead><tr><th></th><th>标准词</th><th>别名</th><th>日期</th><th>文章数</th><th>代表链接</th><th>操作</th></tr></thead><tbody>${result.items.map(row => { const url = safeUrl(row.article_url); return `<tr><td><input type="checkbox" data-hotword-select value="${esc(row.id)}" aria-label="选择热词"></td><td>${display(row.hotword)}</td><td>${display((row.aliases || []).join('、'))}</td><td>${display(row.stat_date)}</td><td>${display(row.article_count)}</td><td>${url ? `<a href="${esc(url)}" target="_blank" rel="noreferrer">打开</a>` : '<span class="dash">—</span>'}</td><td><button class="button button-small button-ghost" data-hotword-edit="${esc(row.id)}" ${writeDisabled() ? 'disabled' : ''}>编辑</button><button class="button button-small button-danger" data-hotword-delete="${esc(row.id)}" ${writeDisabled() ? 'disabled' : ''}>删除</button></td></tr>` }).join('')}</tbody></table></div>${pager(result, 'hotwords')}` : '<div class="empty">暂无热词。</div>'
    host.querySelectorAll('[data-hotword-select]').forEach(node => node.addEventListener('change', updateMergeButton))
    host.querySelectorAll('[data-hotword-edit]').forEach(node => node.addEventListener('click', () => openHotword(node.dataset.hotwordEdit)))
    host.querySelectorAll('[data-hotword-delete]').forEach(node => node.addEventListener('click', () => removeHotword(node.dataset.hotwordDelete)))
    bindPager('hotwords', loadHotwords)
  } catch (error) { host.innerHTML = `<div class="error-box">${esc(errorText(error))}</div>`; apiError(error) }
}

async function openHotword(id) {
  openDrawer('<div class="loading">加载热词详情…</div>')
  try {
    const result = await api.get(`/api/hotwords/${encodeURIComponent(id)}`, { key: `hotword:${id}` })
    const item = result.item
    $('#drawer').innerHTML = `<div class="drawer-head"><div><p class="eyebrow">HOTWORD DETAIL</p><h2>${display(item.hotword)}</h2><p class="muted">${display(item.stat_date)}</p></div><button class="drawer-close" data-close-drawer aria-label="关闭热词编辑">×</button></div>${writeHint()}<form class="form-stack" id="hotword-edit"><div class="field"><label>标准词</label><input name="hotword" maxlength="50" value="${esc(item.hotword)}" required></div><div class="field"><label>aliases（逗号分隔）</label><input name="aliases" value="${esc((item.aliases || []).join(', '))}" placeholder="别名"></div><div class="field"><label>代表链接（可选）</label><input name="article_url" value="${esc(item.article_url || '')}" placeholder="https://…"></div><div class="card-meta">日期：${display(item.stat_date)}<br>文章数：${display(item.article_count)}<br>article_keys：${display((item.article_keys || []).length)} 个（只读）<br><span class="muted">编辑使用 expected_snapshot；热词表没有版本列，并发限制见服务端检查。</span></div><div class="form-actions"><button class="button button-ghost" type="button" data-close-drawer>取消</button><button class="button button-danger" type="button" id="hotword-delete-detail" ${writeDisabled() ? 'disabled' : ''}>删除</button><button class="button" type="submit" ${writeDisabled() ? 'disabled' : ''}>保存</button></div></form>`
    $('#drawer').querySelectorAll('[data-close-drawer]').forEach(node => node.addEventListener('click', closeDrawer))
    $('#hotword-edit').addEventListener('submit', event => saveHotword(event, item))
    $('#hotword-delete-detail').addEventListener('click', () => removeHotword(item.id, item))
  } catch (error) { $('#drawer').innerHTML = `<div class="error-box">${esc(errorText(error))}</div>`; apiError(error) }
}

async function saveHotword(event, item) {
  event.preventDefault()
  const form = event.currentTarget
  const payload = { hotword: form.elements.hotword.value.trim(), aliases: form.elements.aliases.value.split(/[，,\n]/u).map(value => value.trim()).filter(Boolean), article_url: form.elements.article_url.value.trim() || null, expected_snapshot: item }
  const submit = form.querySelector('button[type="submit"]'); submit.disabled = true
  try { await api.mutate(`/api/hotwords/${encodeURIComponent(item.id)}`, { method: 'PATCH', body: payload }); api.invalidate('hotwords:list'); closeDrawer(); toast('热词配置已保存'); loadHotwords() } catch (error) { apiError(error) } finally { if (submit.isConnected) submit.disabled = writeDisabled() }
}

async function removeHotword(id, loadedItem = null) {
  if (!confirmAction('确认删除该热词？article_keys 不会自动删除文章。')) return
  try {
    const item = loadedItem || (await api.get(`/api/hotwords/${encodeURIComponent(id)}`, { key: `hotword:${id}` })).item
    await api.mutate(`/api/hotwords/${encodeURIComponent(id)}`, { method: 'DELETE', body: { expected_snapshot: item } })
    api.invalidate('hotwords:list'); closeDrawer(); toast('热词已删除'); loadHotwords()
  } catch (error) { apiError(error) }
}

function updateMergeButton() { const selected = document.querySelectorAll('[data-hotword-select]:checked'); const button = $('#hotword-merge'); if (button) { button.disabled = selected.length < 2 || writeDisabled(); button.textContent = selected.length >= 2 ? `合并选中项（${selected.length}）` : '合并选中项' } }
async function mergeHotwords() { const ids = [...document.querySelectorAll('[data-hotword-select]:checked')].map(node => Number(node.value)); if (ids.length < 2) return; try { const preview = await api.mutate('/api/hotwords/merge-preview', { method: 'POST', body: { ids, target_id: ids[0] } }); const target = preview.computed?.hotword || ''; if (!confirmAction(`保留“${target}”并合并 ${ids.length} 条热词？`)) return; const result = await api.mutate('/api/hotwords/merge', { method: 'POST', body: { ids, target_id: preview.targetId, expected_snapshots: preview.snapshots } }); toast(result.status === 'success' ? '热词合并完成' : '热词合并部分完成，请核对结果'); api.invalidate('hotwords:list'); loadHotwords() } catch (error) { apiError(error) } }

function openDrawer(html) { const drawer = $('#drawer'); drawer.innerHTML = html; drawer.classList.add('open'); drawer.setAttribute('aria-hidden', 'false'); document.body.insertAdjacentHTML('beforeend', '<div class="drawer-backdrop" data-drawer-backdrop></div>'); drawer.querySelector('[data-close-drawer]')?.focus() }
function closeDrawer() { $('#drawer').classList.remove('open', 'strategy-drawer-open'); $('#drawer').setAttribute('aria-hidden', 'true'); document.querySelector('[data-drawer-backdrop]')?.remove() }
async function render() {
  const vanillaShell = $('#vanilla-app-shell')
  const reactRoot = $('#strategy-react-root')
  if (state.view === 'strategies') {
    vanillaShell.hidden = true
    reactRoot.hidden = false
    if (typeof window.mountStrategyApp === 'function') return window.mountStrategyApp(reactRoot)
    reactRoot.innerHTML = '<div class="loading">正在加载采集策略页面…</div>'
    return
  }
  window.unmountStrategyApp?.()
  vanillaShell.hidden = false
  reactRoot.hidden = true
  renderNav()
  state.token = tokenStore.get()
  $('#token-input').value = state.token
  if (state.view === 'accounts') return renderAccounts()
  if (state.view === 'articles') return renderArticles()
  if (state.view === 'rules') return renderRules()
  if (state.view === 'hotwords') { await renderHotwords(); $('#hotword-merge')?.addEventListener('click', mergeHotwords); return }
}

if (typeof window !== 'undefined' && typeof document !== 'undefined') {
  state.view = new URL(location.href).searchParams.get('view') || 'accounts'; restoreViewState(state.view); $('#token-input').addEventListener('change', event => { state.token = event.target.value.trim(); tokenStore.set(state.token); render() }); $('#refresh-button').addEventListener('click', () => { api.clear(); render(); refreshHealth() }); document.addEventListener('click', event => { if (event.target.matches('[data-close-drawer], [data-drawer-backdrop]')) closeDrawer() }); document.addEventListener('keydown', event => { if (event.key === 'Escape') closeDrawer(); else handleAccountKeyboard(event) }); window.addEventListener('popstate', () => { rememberViewState(); state.view = new URL(location.href).searchParams.get('view') || 'accounts'; restoreViewState(state.view); render() }); refreshHealth(); render()
}
